wrong_code.class:
// File: Main.java containing two top-level classes!
// Danger: Another file (e.g. Desert.java) might also define Utensil or Dessert!
class Utensil {
    static final String NAME = "pan";
}

class Dessert {
    static final String NAME = "cake";
}

public class Main {
    public static void main(String[] args) {
        System.out.println(Utensil.NAME + " " + Dessert.NAME);
    }
}

wrong_code.call_site:
// If another file Dessert.java also defines Utensil and Dessert:
// javac Main.java Dessert.java -> prints: "pan cake"
// javac Dessert.java Main.java -> prints: "pot pie"!
// Compiling code in different order changes the program behavior completely!

right_code.class:
// Clean solution 1: Put each top-level class into its own file (Utensil.java, Dessert.java)
// Clean solution 2: If classes are small helpers, make them static member classes inside the main class!
public class SafeMain {
    private static class Utensil {
        static final String NAME = "pan";
    }

    private static class Dessert {
        static final String NAME = "cake";
    }

    public static void main(String[] args) {
        System.out.println(Utensil.NAME + " " + Dessert.NAME); // Deterministic always!
    }
}

right_code.call_site:
public class Main {
    public static void main(String[] args) {
        SafeMain.main(args); // Consistent, safe, completely immune to compile order variations
    }
}
